import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./SpendingPriority.css";

function SpendingPriority({ onNext }) {
  const navigate = useNavigate();

  const categories = [
    "Food & Groceries",
    "Shopping",
    "Bills",
    "Health",
    "Entertainment",
    "Transport"
  ];

  const [priorities, setPriorities] = useState({});

  const handleCardClick = (category) => {
    setPriorities((prev) => ({
      ...prev,
      [category]: prev[category] ?? 0
    }));
  };

  const handleSliderChange = (category, value) => {
    setPriorities((prev) => ({
      ...prev,
      [category]: Number(value)
    }));
  };

  const handleContinue = () => {
    if (onNext) onNext(priorities);
    navigate("/budget");
  };

  return (
    <div className="income-container">
      <h2 className="income-title">Spending Priority</h2>
      <p className="income-subtitle">Select categories and set priority</p>

      <div className="income-grid">
        {categories.map((category) => (
          <div
            key={category}
            className="income-card"
            onClick={() => handleCardClick(category)}
          >
            <div className="income-name">{category}</div>

            {priorities[category] !== undefined && (
              <input
                type="range"
                min="0"
                max="5"
                value={priorities[category]}
                onChange={(e) =>
                  handleSliderChange(category, e.target.value)
                }
                style={{ width: "100%", marginTop: "15px" }}
              />
            )}
          </div>
        ))}
      </div>

      <button className="next-button" onClick={handleContinue}>
        Continue
      </button>
    </div>
  );
}

export default SpendingPriority;
